REPLACE INTO report_templates (code,title,cadence,requires_evidence,definition,is_active,loaded_at) VALUES ('monthly_leadership','Monthly Leadership & Performance Report','monthly',0,'{"sections":[{"key":"A","auto":["identity"],"title":"Identity & reporting period","fields":[]},{"key":"B","title":"Executive leadership commentary","fields":[{"key":"improved","type":"textarea","label":"What materially improved this month?","required":true},{"key":"declined","type":"textarea","label":"What materially declined or remains unresolved?","required":true},{"key":"decision","type":"textarea","label":"What decision or support is required from the next reporting level?","required":true}]},{"key":"C","auto":["leadership","pipeline"],"title":"Leadership structure & coverage","fields":[{"key":"leadership_issues","type":"textarea","label":"Leadership issues requiring intervention"},{"key":"recruitment_priorities","type":"textarea","label":"Areas requiring recruitment or strengthening"}]},{"key":"D","auto":["compliance"],"title":"Reporting compliance under my leadership","fields":[{"key":"noncompliance","type":"textarea","label":"Explain significant non-compliance","requiredWhen":"compliance.overdue>0"}]},{"key":"E","auto":["membership","activities"],"title":"Membership, mobilisation & retention","fields":[{"key":"women_reached","type":"number","label":"Women newly reached (not already recorded)"},{"key":"new_areas","type":"textarea","label":"New geographical areas reached"},{"key":"retention","type":"textarea","label":"Retention concerns and underserved areas"}]},{"key":"F","auto":["learning"],"title":"Learning & WODDI Institute","fields":[{"key":"learning_barriers","type":"textarea","label":"Learning barriers identified and action taken"}]},{"key":"G","auto":["programmes"],"title":"Programmes & activities","fields":[{"key":"outcomes","type":"textarea","label":"Major outcomes and lessons (only what the activity records do not say)"}]},{"key":"H","auto":["meetings"],"title":"Meetings, decisions & actions","fields":[{"key":"decisions","type":"textarea","label":"Major decisions and outstanding actions requiring escalation"}]},{"key":"I","auto":["tasks"],"title":"Tasks & deliverables","fields":[{"key":"overdue_note","type":"textarea","label":"Explanation for overdue, blocked or decision-dependent items","requiredWhen":"tasks.overdue>0"}]},{"key":"J","title":"Partnerships & stakeholder engagement","fields":[{"key":"stakeholders","max":10,"cols":[{"key":"stakeholder","label":"Stakeholder / organisation"},{"key":"category","type":"select","label":"Category","options":["Women''s organisation","Professional body","Institution","Public body","Private sector","Media","Development partner","Community organisation","Other"]},{"key":"purpose","label":"Purpose"},{"key":"date","type":"date","label":"Date"},{"key":"outcome","label":"Outcome"},{"key":"commitment","label":"Commitment made"},{"key":"next","label":"Next action"},{"key":"deadline","type":"date","label":"Deadline"}],"type":"rows","label":"Engagements this month"}]},{"key":"K","title":"Communications & visibility","fields":[{"key":"comms_ack","type":"number","label":"Official communications acknowledged"},{"key":"comms_distributed","type":"number","label":"Network information distributed"},{"key":"campaigns","type":"number","label":"Campaigns supported"},{"key":"visibility","type":"number","label":"Local media or visibility activities"},{"key":"comms_issues","type":"textarea","label":"Communication issues"}]},{"key":"L","auto":["support"],"title":"Digital access & inclusion","fields":[{"key":"wdos_assist","type":"number","label":"Members requiring WDOS assistance"},{"key":"institute_cases","type":"number","label":"Institute access support cases"},{"key":"barriers","type":"textarea","label":"Connectivity, language or accessibility barriers"},{"key":"group_support","type":"textarea","label":"Supported group or viewing arrangements"}]},{"key":"M","title":"Financial / resource accountability","fields":[{"key":"budget_ref","type":"text","label":"Approval / budget reference"},{"key":"approved_amount","type":"number","label":"Approved amount"},{"key":"received","type":"number","label":"Amount received"},{"key":"spent","type":"number","label":"Actual expenditure"},{"key":"commitments","type":"textarea","label":"Outstanding commitments"},{"key":"variance","type":"textarea","label":"Explanation of variance"}],"conditional":"finance"},{"key":"N","auto":["issues"],"title":"Risks, issues & escalations","fields":[{"key":"risks","max":10,"cols":[{"key":"category","type":"select","label":"Category","options":["Leadership","Membership","Programme","Learning","Technology","Communications","Partnership","Finance","Governance","Data","Operational","Reputation","Other"]},{"key":"severity","type":"select","label":"Severity","options":["green","amber","red","critical"]},{"key":"issue","label":"Issue"},{"key":"action","label":"Action already taken"},{"key":"owner","label":"Owner"},{"key":"support","label":"Support or decision required"},{"key":"deadline","type":"date","label":"Deadline"}],"type":"rows","label":"New non-confidential issues (confidential matters go through the Confidential Reporting channel)"}]},{"key":"O","title":"Top priorities for next month","fields":[{"key":"priorities","max":5,"cols":[{"key":"priority","label":"Priority"},{"key":"deliverable","label":"Deliverable"},{"key":"owner","label":"Owner"},{"key":"deadline","type":"date","label":"Deadline"},{"key":"support","label":"Support needed"}],"type":"rows","label":"Maximum five; approved priorities become tasks"}]},{"key":"P","title":"Leader declaration","fields":[{"key":"declaration","type":"check","label":"I confirm that this report is accurate to the best of my knowledge, that supporting evidence has been appropriately recorded or referenced, and that confidential matters have been reported only through the authorised confidential channel.","required":true}]}],"levels":["country","state_region","district_lga","chapter"],"source_cadence":"monthly","version":1}',1,'2026-11-10 12:00:00');
REPLACE INTO report_templates (code,title,cadence,requires_evidence,definition,is_active,loaded_at) VALUES ('weekly_pulse','Weekly Accountability Pulse','weekly',0,'{"sections":[{"key":"A","auto":["identity","tasks","activities","meetings","compliance","issues"],"title":"This week (system-generated)","fields":[]},{"key":"B","title":"Leader input","fields":[{"key":"achievement","type":"textarea","label":"Major achievement this week","required":true},{"key":"blocker","type":"textarea","label":"Major blocker or risk"},{"key":"decision","type":"textarea","label":"Decision or support required"},{"key":"priorities","max":5,"cols":[{"key":"priority","label":"Priority"},{"key":"owner","label":"Owner"},{"key":"deadline","type":"date","label":"Deadline"}],"type":"rows","label":"Top priorities for next week (maximum five)"}]}],"levels":["country","state_region","district_lga","chapter"],"source_cadence":"weekly","version":1}',1,'2026-11-10 12:00:00');
REPLACE INTO report_templates (code,title,cadence,requires_evidence,definition,is_active,loaded_at) VALUES ('activity_report','Programme / Activity Report','adhoc',1,'{"sections":[{"key":"A","auto":["identity"],"title":"Activity identity","fields":[{"key":"title","type":"text","label":"Activity title","required":true},{"key":"date","type":"date","label":"Date","required":true},{"key":"format","type":"select","label":"Format","options":["In person","Virtual","Hybrid"],"required":true},{"key":"programme","type":"text","label":"Programme"}]},{"key":"B","title":"Approval","fields":[{"key":"approval_ref","type":"text","label":"Approval reference"},{"key":"approved_by","type":"text","label":"Approving authority"},{"key":"approval_date","type":"date","label":"Approval date"}]},{"key":"C","title":"Objective and delivery","fields":[{"key":"objective","type":"textarea","label":"What the activity was intended to achieve","required":true},{"key":"delivery","type":"textarea","label":"What was actually delivered","required":true}]},{"key":"D","title":"Participation and reach","fields":[{"key":"registered","type":"number","label":"Registered"},{"key":"attended","type":"number","label":"Attended","required":true},{"key":"categories","type":"text","label":"Participant categories reached"},{"key":"communities","type":"number","label":"Communities reached"}]},{"key":"E","title":"Outputs, outcomes and referrals","fields":[{"key":"outputs","type":"textarea","label":"Immediate deliverables produced"},{"key":"outcomes","type":"textarea","label":"What changed or was achieved","required":true},{"key":"referrals","type":"number","label":"Referrals generated (membership, leadership, learning, support)"}]},{"key":"F","title":"Financial / resource","fields":[{"key":"approved_amount","type":"number","label":"Approved amount"},{"key":"spent","type":"number","label":"Actual expenditure"},{"key":"variance","type":"textarea","label":"Explanation of variance"}],"conditional":"finance"},{"key":"G","title":"Issues, lessons and follow-up","fields":[{"key":"issues","type":"textarea","label":"Operational issues (non-confidential)"},{"key":"lessons","type":"textarea","label":"Lessons and recommendations"},{"key":"followups","max":5,"cols":[{"key":"action","label":"Action"},{"key":"owner","label":"Owner"},{"key":"deadline","type":"date","label":"Deadline"}],"type":"rows","label":"Follow-up actions"}]},{"key":"P","title":"Declaration","fields":[{"key":"declaration","type":"check","label":"I confirm this report is accurate and evidence has been referenced.","required":true}]}],"levels":["country","state_region","district_lga","chapter"],"source_cadence":"event","version":1}',1,'2026-11-10 12:00:00');
REPLACE INTO report_templates (code,title,cadence,requires_evidence,definition,is_active,loaded_at) VALUES ('meeting_actions','Meeting Decisions & Action Report','adhoc',0,'{"sections":[{"key":"A","auto":["identity","meeting"],"title":"Meeting","fields":[{"key":"meeting_type","type":"select","label":"Meeting type","options":["Leadership check-in","Coordination","Chapter meeting","Programme","Stakeholder","Other"],"required":true},{"key":"title","type":"text","label":"Title","required":true},{"key":"date","type":"date","label":"Date","required":true},{"key":"chair","type":"text","label":"Chair","required":true},{"key":"secretary","type":"text","label":"Secretary"},{"key":"attendance","type":"number","label":"Attendance (number)"}]},{"key":"B","title":"Agenda and discussion","fields":[{"key":"agenda","type":"textarea","label":"Agenda points","required":true},{"key":"summary","type":"textarea","label":"Key discussion summary (concise)"}]},{"key":"C","title":"Decisions and actions","fields":[{"key":"actions","max":15,"cols":[{"key":"decision","label":"Decision"},{"key":"action","label":"Action"},{"key":"owner","label":"Owner"},{"key":"deadline","type":"date","label":"Deadline"}],"type":"rows","label":"One decision per row; approved actions become tasks","required":true},{"key":"next_meeting","type":"date","label":"Next meeting"}]},{"key":"P","title":"Declaration","fields":[{"key":"declaration","type":"check","label":"I confirm this record is accurate.","required":true}]}],"levels":["country","state_region","district_lga","chapter"],"source_cadence":"event","version":1}',1,'2026-11-10 12:00:00');
REPLACE INTO report_templates (code,title,cadence,requires_evidence,definition,is_active,loaded_at) VALUES ('exit_handover','Exit, Transition & Handover','adhoc',0,'{"sections":[{"key":"A","auto":["identity","leadership","tasks","compliance","meetings","issues"],"title":"Auto-pulled handover position","fields":[]},{"key":"B","title":"Transition","fields":[{"key":"successor","type":"text","label":"Successor or receiving authority (where known)"},{"key":"effective","type":"date","label":"Effective date","required":true},{"key":"open_reports","type":"textarea","label":"Open or returned reports: complete, transfer or authorised exception"},{"key":"open_tasks","type":"textarea","label":"Open tasks and overdue actions: owner, deadline, transition note","required":true},{"key":"programmes","type":"textarea","label":"Active programmes: transfer of responsibility and evidence"},{"key":"stakeholders","type":"textarea","label":"Stakeholder engagements and commitments transferred"},{"key":"records","type":"textarea","label":"Documents, evidence and records: official storage confirmed"},{"key":"assets","type":"textarea","label":"Assets or resources returned or transferred"},{"key":"access","type":"textarea","label":"Official access and accounts to disable or transfer"}]},{"key":"P","title":"Declaration","fields":[{"key":"declaration","type":"check","label":"I confirm the handover information is complete; confidential matters were transferred only through the restricted channel.","required":true}]}],"levels":["country","state_region","district_lga","chapter"],"source_cadence":"transition","version":1}',1,'2026-11-10 12:00:00');
